const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const props = item.props || {};
  const words = String(props.headline).split(' ');
  const hi = Number(props.highlightIndex);
  const bg = props.transparentBackground ? 'transparent' : props.paperColor;
  const rootStyle = { position: 'absolute', inset: 0, backgroundColor: bg };

  return (
    <div style={{ ...rootStyle, display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: 80 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 32 }}>
        <div style={{ width: 44, height: 4, backgroundColor: props.inkColor }} />
        <span style={{ fontFamily: props.font, fontWeight: 800, fontSize: 22, letterSpacing: '0.18em', textTransform: 'uppercase', color: props.inkColor, opacity: 0.65 }}>{props.kicker}</span>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.1em 0.26em', fontFamily: props.font, fontWeight: 900, fontSize: 132, lineHeight: 0.96, letterSpacing: '-0.025em', color: props.inkColor }}>
        {words.map((w, i) => {
          const start = i * 5;
          const s = spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 180 } });
          const op = Math.min(1, s * 2);
          const sweep = interpolate(frame - start - 8, [0, 10], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
          const isHi = i === hi;
          const wrapStyle = { display: 'inline-block', position: 'relative', transform: `scale(${s})`, opacity: op };
          if (isHi) {
            return (
              <span key={i} style={{ ...wrapStyle, padding: '0 0.12em' }}>
                <span style={{ position: 'relative', zIndex: 2 }}>{w}</span>
                <span style={{ position: 'absolute', inset: 0, zIndex: 1, backgroundColor: props.accentColor, transform: `scaleX(${sweep})`, transformOrigin: 'left center' }} />
              </span>
            );
          }
          return <span key={i} style={wrapStyle}>{w}</span>;
        })}
      </div>
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const props = item.props || {};
  const target = Number(props.value);
  const dur = 30;
  const eased = interpolate(frame, [0, dur], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic) });
  const shown = Math.round(target * eased);
  const under = interpolate(frame - dur, [0, 14], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const bg = props.transparentBackground ? 'transparent' : props.paperColor;
  const rootStyle = { position: 'absolute', inset: 0, backgroundColor: bg };

  return (
    <div style={{ ...rootStyle, display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: 80 }}>
      <div style={{ fontFamily: props.font, fontWeight: 800, fontSize: 24, letterSpacing: '0.16em', textTransform: 'uppercase', color: props.inkColor, opacity: 0.65, marginBottom: 10 }}>{props.label}</div>
      <div style={{ fontFamily: props.font, fontWeight: 900, fontSize: 300, lineHeight: 0.88, letterSpacing: '-0.04em', color: props.inkColor, display: 'flex', alignItems: 'flex-start' }}>
        {shown}
        <span style={{ fontSize: 96, fontWeight: 800, color: props.alertColor, marginLeft: 10, marginTop: 26 }}>{props.suffix}</span>
      </div>
      <div style={{ height: 9, width: '46%', backgroundColor: props.accentColor, transform: `scaleX(${under})`, transformOrigin: 'left center', marginTop: 18 }} />
      <div style={{ fontFamily: props.font, fontSize: 18, color: props.inkColor, opacity: 0.6, marginTop: 24 }}>{props.source}</div>
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const props = item.props || {};
  const parseBars = (raw) => {
    try {
      const v = JSON.parse(String(raw));
      return Array.isArray(v) ? v : [];
    } catch {
      return [];
    }
  };
  const bars = parseBars(props.dataJson);
  const bg = props.transparentBackground ? 'transparent' : props.paperColor;
  const rootStyle = { position: 'absolute', inset: 0, backgroundColor: bg };

  return (
    <div style={{ ...rootStyle, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', padding: 80 }}>
      <div style={{ fontFamily: props.font, fontWeight: 900, fontSize: 52, letterSpacing: '-0.01em', color: props.inkColor, marginBottom: 44, maxWidth: '80%' }}>{props.title}</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
        {bars.map((b, i) => {
          const start = 6 + i * 8;
          const grow = interpolate(frame - start, [0, 22], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic) });
          const pct = (Number(b.pct) || 0) * grow;
          const fill = b.acc ? props.alertColor : props.barColor;
          const rowStyle = { display: 'grid', gridTemplateColumns: '240px 1fr 110px', alignItems: 'center', gap: 20 };
          return (
            <div key={i} style={rowStyle}>
              <div style={{ fontFamily: props.font, fontWeight: 600, fontSize: 26, color: props.inkColor }}>{b.name}</div>
              <div style={{ height: 32, backgroundColor: 'rgba(21,20,15,0.08)', borderRadius: 4, overflow: 'hidden' }}>
                <div style={{ height: '100%', width: pct + '%', backgroundColor: fill, borderRadius: 4 }} />
              </div>
              <div style={{ fontFamily: props.font, fontWeight: 600, fontSize: 24, textAlign: 'right', color: props.inkColor }}>{b.val}%</div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const props = item.props || {};
  const barGrow = interpolate(frame, [0, 12], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic) });
  const wipe = interpolate(frame - 8, [0, 14], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const bg = props.transparentBackground ? 'transparent' : props.paperColor;
  const rootStyle = { position: 'absolute', inset: 0, backgroundColor: bg, display: 'flex', alignItems: 'flex-end', padding: 80 };

  return (
    <div style={rootStyle}>
      <div style={{ display: 'flex', alignItems: 'stretch' }}>
        <div style={{ width: 10, backgroundColor: props.accentColor, alignSelf: 'stretch', transform: `scaleY(${barGrow})`, transformOrigin: 'top center' }} />
        <div style={{ overflow: 'hidden' }}>
          <div style={{ transform: `translateX(${(1 - wipe) * 100}%)`, padding: '12px 26px' }}>
            <div style={{ fontFamily: props.font, fontWeight: 900, fontSize: 58, letterSpacing: '-0.01em', lineHeight: 1, color: props.inkColor }}>{props.name}</div>
            <div style={{ fontFamily: props.font, fontWeight: 600, fontSize: 22, letterSpacing: '0.04em', color: props.inkSoftColor, marginTop: 8 }}>{props.role}</div>
          </div>
        </div>
      </div>
    </div>
  );
};

